import org.jsoup.parser.*;
import org.junit.Test;
import java.io.StringReader;
import java.util.List;
import org.jsoup.nodes.*;
import static org.junit.Assert.*;

public class XmlTreeBuilderTest {

	@Test
	public void initialiseParseTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.initialiseParse(new StringReader("<root></root>"), "https://baseUri.com", new Parser(xmlTreeBuilder));
		Document document = xmlTreeBuilder.getDocument();
		assertNotNull(document);
	}

	@Test
	public void parseReaderInputTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		Document document = xmlTreeBuilder.parse(new StringReader("<root></root>"), "https://baseUri.com");
		assertNotNull(document);
	}

	@Test
	public void parseStringInputTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		Document document = xmlTreeBuilder.parse("<root></root>", "https://baseUri.com");
		assertNotNull(document);
	}

	@Test
	public void newInstanceTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		XmlTreeBuilder newInstance = xmlTreeBuilder.newInstance();
		assertNotNull(newInstance);
		assertNotEquals(xmlTreeBuilder, newInstance);
	}

	@Test
	public void processTokenTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		boolean result = xmlTreeBuilder.process(new Token.StartTag());
		assertTrue(result);
	}

	@Test
	public void insertNodeTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insertNode(new TextNode("sample text"));
		assertNotNull(xmlTreeBuilder.getDocument().text());
	}

	@Test
	public void insertNodeTokenTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		TextNode textNode = new TextNode("sample text");
		Token token = new Token.Character("sample text");
		xmlTreeBuilder.insertNode(textNode, token);
		assertNotNull(xmlTreeBuilder.getDocument().text());
	}

	@Test
	public void insertTokenStartTagTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insert(new Token.StartTag());
		assertNotNull(xmlTreeBuilder.getDocument().text());
	}

	@Test
	public void insertTokenCommentTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insert(new Token.Comment("comment"));
		assertNotNull(xmlTreeBuilder.getDocument().childNodes());
	}

	@Test
	public void insertTokenCharacterTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insert(new Token.Character("character"));
		assertNotNull(xmlTreeBuilder.getDocument().text());
	}

	@Test
	public void insertTokenDoctypeTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insert(new Token.Doctype("doctype", "", "", true));
		assertNotNull(xmlTreeBuilder.getDocument().childNodes());
	}

	@Test
	public void popStackToCloseTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		xmlTreeBuilder.insert(new Token.StartTag("parent"));
		xmlTreeBuilder.insert(new Token.StartTag());
		xmlTreeBuilder.popStackToClose(new Token.EndTag());
		assertNotNull(xmlTreeBuilder.getDocument().childNodes());
	}

	@Test
	public void parseFragmentTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		List<Node> nodes = xmlTreeBuilder.parseFragment("<fragment></fragment>", "https://baseUri.com", new Parser(xmlTreeBuilder));
		assertNotNull(nodes);
		assertFalse(nodes.isEmpty());
	}

	@Test
	public void parseFragmentContextTest() {
		XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
		Document document = xmlTreeBuilder.parse("<fragment><child></child></fragment>", "https://baseUri.com");
		Element context = document.child(0);
		List<Node> nodes = xmlTreeBuilder.parseFragment("<fragment><child2></child2></fragment>", context, "https://baseUri.com", new Parser(xmlTreeBuilder));
		assertNotNull(nodes);
		assertFalse(nodes.isEmpty());
	}
}
